export type HorizontalAlign = "left" | "center" | "right";

/**
 * A globally unique, time-ordered identifier (UUID v7).
 *
 * UUID v7 sorts by creation time and can be generated on any machine without
 * coordination, which keeps the door open for syncing libraries between
 * several operator computers later on.
 *
 * Serialized as the usual hyphenated string, e.g.
 * `"01920c7e-5a4b-7c3d-9e8f-0a1b2c3d4e5f"`.
 */
export type Id = string;

/**
 * What a schedule item shows.
 */
export type ItemContent =
  | {
      type: "song";
      /**
       * The song. Its id links it back to the library.
       */
      song: Song;
    }
  | {
      type: "text";
      /**
       * Title shown in the schedule.
       */
      title: string;
      /**
       * The text; blank lines separate slides.
       */
      text: string;
    }
  | {
      type: "scripture";
      /**
       * The passage.
       */
      passage: Passage;
      /**
       * The passage written out, e.g. "John 3:16–18", for showing in
       * the schedule without needing the book names.
       */
      reference: string;
      /**
       * The text in each translation, shown side by side.
       */
      translations: Array<TranslationText>;
      /**
       * How the passage is split into slides.
       */
      options: ScriptureOptions;
    }
  | {
      type: "media";
      /**
       * The media item (the file travels with a saved schedule).
       */
      media: MediaItem;
    }
  | {
      type: "camera";
      /**
       * Which camera.
       */
      camera: CameraRef;
    }
  | {
      type: "countdown";
      /**
       * Title in the schedule, e.g. "Countdown to 10:30".
       */
      title: string;
      /**
       * What it counts down to and what happens at zero.
       */
      countdown: CountdownSlide;
    }
  | {
      type: "deck";
      /**
       * The deck. Its id links it back to the library (a slideshow made
       * in the schedule is not in the library).
       */
      deck: SlideDeck;
    }
  | {
      type: "slides";
      /**
       * The presentation's name.
       */
      name: string;
      /**
       * Its pages, in order (the files travel with a saved schedule).
       */
      pages: Array<MediaItem>;
    }
  | {
      type: "playlist";
      /**
       * The playlist's name.
       */
      name: string;
      /**
       * The tracks, in order (the files travel with a saved schedule).
       */
      tracks: Array<MediaItem>;
    };

/**
 * How a schedule item overrides the normal look.
 */
export type ItemLook = {
  /**
   * A theme for this item only (a copy; see the [module docs](self)).
   */
  theme: ThemeRecord | null;
  /**
   * A background for this item only, replacing the theme's.
   */
  background: Background | null;
};

/**
 * The church logo, shown by the Logo button: a picture, or a video that
 * plays on a loop, without sound.
 */
export type Logo = {
  /**
   * The file.
   */
  media: MediaRef;
  /**
   * Picture or video (never sound).
   */
  kind: MediaKind;
};

/**
 * The outcome of resolving a look: the theme to draw with, and what it
 * came from, so it can be refreshed when the library changes.
 */
export type Look = {
  /**
   * The library theme used, if any. `None` for an embedded copy that the
   * library does not have, or when the library is empty.
   */
  themeId: Id | null;
  /**
   * The theme, with any background override already applied.
   */
  theme: Theme;
  /**
   * The background override, kept so it can be re-applied when the
   * theme is refreshed.
   */
  backgroundOverride: Background | null;
};

/**
 * How an image or video fills a screen of a different shape.
 */
export type MediaFit = "cover" | "contain" | "stretch";

/**
 * An image or video in the media library.
 */
export type MediaItem = {
  /**
   * Unique identifier.
   */
  id: Id;
  /**
   * Image or video.
   */
  kind: MediaKind;
  /**
   * The name shown in the library, usually the original file name
   * without its extension.
   */
  name: string;
  /**
   * The file name inside the library's media folder.
   */
  file: string;
  /**
   * Width in pixels, if known.
   */
  width: number | null;
  /**
   * Height in pixels, if known.
   */
  height: number | null;
  /**
   * Length of a video in milliseconds, if known.
   */
  durationMs: number | null;
  /**
   * File size in bytes.
   */
  sizeBytes: number;
  /**
   * When it was imported.
   */
  createdAt: number;
  /**
   * The presentation this is a page of, if any. Pages are kept out of
   * the Media tab and shown in the Presentations tab instead.
   */
  collection: Id | null;
  /**
   * How it fills the screen (see [`MediaScaling`]).
   */
  scaling: MediaScaling;
};

/**
 * What kind of file a media item is.
 */
export type MediaKind = "image" | "video" | "audio";

/**
 * A pointer to a file in the media library.
 */
export type MediaRef = {
  /**
   * The media item's id.
   */
  id: Id;
  /**
   * Its file name inside the library's media folder, e.g. `"0192….mp4"`.
   */
  file: string;
};

/**
 * How a picture or video fills the screen, chosen for the file itself in
 * the Media tab and used wherever the file fills the screen: as a theme's
 * or a slide's background, or shown on its own. (A picture placed on a
 * slide in the canvas editor has its own fit, set in the Inspector.)
 *
 * As in EasyWorship, most files are left on `Automatic`.
 */
export type MediaScaling = "automatic" | "stretch" | "maintain" | "zoom";

/**
 * An outline drawn around each glyph.
 */
export type Outline = {
  /**
   * CSS color of the outline.
   */
  color: string;
  /**
   * Width in reference pixels.
   */
  width: number;
};

/**
 * Everything an output screen needs to draw right now.
 */
export type OutputState = {
  /**
   * The live slide, or `None` when nothing is live (the screen is black).
   */
  frame: RenderFrame | null;
  /**
   * Which parts of the output are hidden.
   */
  flags: DisplayFlags;
  /**
   * How to animate into this state.
   */
  transition: Transition;
  /**
   * Playback of the live video background, if there is one.
   */
  video: VideoPlayback | null;
  /**
   * The church logo, shown when [`DisplayFlags::logo`] is on. Without
   * one, the Logo button shows the background with no text.
   */
  logo: Logo | null;
  /**
   * An alert over the slides, if one is showing.
   */
  alert: Alert | null;
  /**
   * What the stream output shows (see [`crate::stream`]).
   */
  stream: StreamOutput;
  /**
   * Increases by one every time the output changes. Lets renderers that
   * connect late, or miss an event, tell whether they are up to date.
   */
  revision: number;
};

/**
 * A presentation loaded into a pane, plus which slide is selected.
 */
export type PaneState = {
  /**
   * The loaded presentation.
   */
  presentation: Presentation;
  /**
   * Index of the selected slide. Always a valid index into
   * `presentation.slides`, except for a presentation with no slides.
   */
  selected: number;
  /**
   * The schedule item the presentation came from, if any.
   */
  scheduleItem: Id | null;
};

/**
 * Where a line of small print goes.
 */
export type Placement = "box" | "afterText";

/**
 * A titled list of slides, styled with one theme.
 */
export type Presentation = {
  /**
   * Identifies this particular presentation instance.
   */
  id: Id;
  /**
   * Where the slides came from.
   */
  source: PresentationSource;
  /**
   * Title shown in the operator UI, e.g. the song title.
   */
  title: string;
  /**
   * The slides, in the order they are shown.
   */
  slides: Array<Slide>;
  /**
   * The theme every slide is drawn with (with any background override
   * already applied).
   */
  theme: Theme;
  /**
   * The library theme `theme` came from, so edits to it can be shown
   * straight away. `None` if it did not come from the library.
   */
  themeId: Id | null;
  /**
   * A background chosen for this item only, re-applied when the theme
   * is refreshed.
   */
  backgroundOverride: Background | null;
  /**
   * Small print shown under the lyrics, e.g. copyright and CCLI number.
   */
  footer: string | null;
  /**
   * Move to the next slide by itself (the operator window keeps time).
   */
  autoAdvance: AutoAdvance | null;
};

/**
 * Where a presentation's slides came from.
 */
export type PresentationSource =
  | {
      type: "song";
      /**
       * The song's id.
       */
      songId: Id;
    }
  | { type: "countdown" }
  | { type: "slides" }
  | {
      type: "deck";
      /**
       * The deck's id.
       */
      deckId: Id;
    }
  | { type: "playlist" }
  | { type: "text" }
  | {
      type: "scripture";
      /**
       * The passage.
       */
      passage: Passage;
    }
  | {
      type: "media";
      /**
       * The media item's id.
       */
      mediaId: Id;
    }
  | { type: "camera" };

/**
 * One slide, resolved and ready to draw.
 */
export type RenderFrame = {
  /**
   * The slide text. Lines are separated by `\n`. For scripture this is a
   * plain-text version; draw [`RenderFrame::scripture`] instead.
   */
  text: string;
  /**
   * Scripture verses in columns, when the slide is scripture.
   */
  scripture: ScriptureSlide | null;
  /**
   * A line shown with the slide, e.g. the reference "John 3:16–17 (KJV)".
   */
  caption: string | null;
  /**
   * The text in styled pieces, when it has bold, italic or underline.
   * Draw this instead of `text` when it is there.
   */
  rich: Array<TextRun> | null;
  /**
   * Text boxes, shapes and pictures, back to front, for a slide made in
   * the canvas editor. Draw these instead of the text and caption.
   */
  elements: Array<SlideElement> | null;
  /**
   * A live countdown, when the slide is one.
   */
  countdown: CountdownFrame | null;
  /**
   * Small print under the text, if any.
   */
  footer: string | null;
  /**
   * The theme to draw with.
   */
  theme: Theme;
};

/**
 * The order of service.
 */
export type Schedule = {
  /**
   * The items, in service order.
   */
  items: Array<ScheduleItem>;
};

/**
 * One entry in a schedule.
 */
export type ScheduleItem = {
  /**
   * Identifies this entry. The same song can be in a schedule twice, as
   * two items with different ids.
   */
  id: Id;
  /**
   * Private notes for the operator, e.g. "Pastor prays after verse 2".
   */
  notes: string;
  /**
   * What the item shows.
   */
  content: ItemContent;
  /**
   * A theme or background for this item only.
   */
  look: ItemLook;
};

/**
 * One translation's part of a scripture slide.
 */
export type ScriptureColumn = {
  /**
   * The translation's short name, e.g. "KJV".
   */
  translation: string;
  /**
   * The verses on this slide.
   */
  verses: Array<VerseLine>;
};

/**
 * How a passage is split into slides.
 */
export type ScriptureOptions = {
  /**
   * The most verses on one slide.
   */
  maxVerses: number;
  /**
   * No longer used: how much fits now comes from the theme (see
   * [`chars_per_column`]). Kept so schedules saved before still load.
   */
  maxChars: number;
  /**
   * Show verse numbers before each verse, or `None` to do as the theme
   * says (see [`VerseNumberStyle`](crate::theme::VerseNumberStyle)).
   */
  verseNumbers: boolean | null;
  /**
   * Move text that does not fit the theme's text box at
   * `min_font_size` on to more slides. Without it, everything up to
   * `max_verses` goes on one slide and shrinks as far as it must.
   */
  autoFlow: boolean;
  /**
   * The smallest font size, in canvas pixels (1920 × 1080), the text may
   * shrink to before the rest goes on the next slide. EasyWorship's
   * "Minimum font size before breaking slide".
   */
  minFontSize: number;
};

/**
 * The structured content of a scripture slide: one column per translation.
 */
export type ScriptureSlide = {
  /**
   * The columns, left to right.
   */
  columns: Array<ScriptureColumn>;
  /**
   * Whether verse numbers are shown, or `None` to do as the theme says.
   */
  verseNumbers: boolean | null;
};

/**
 * Settings that only apply to scripture slides.
 */
export type ScriptureStyle = {
  /**
   * How verse numbers look.
   */
  verseNumbers: VerseNumberStyle;
  /**
   * Show the reference on every slide of a passage, or only on the first.
   */
  referenceOnEverySlide: boolean;
};

/**
 * One section of a song: a label and the lyric text below it.
 */
export type Section = {
  /**
   * The section's label. `None` for text that appears before the first tag.
   */
  label: SectionLabel | null;
  /**
   * The lyric text, with leading and trailing blank lines removed. Blank
   * lines *inside* the text are kept: they mark slide breaks.
   */
  text: string;
};

/**
 * The kind of a song section. Determines its display name and its keyboard
 * shortcut letter in the live view.
 */
export type SectionKind =
  | "verse"
  | "preChorus"
  | "chorus"
  | "bridge"
  | "tag"
  | "intro"
  | "ending"
  | "other";

/**
 * The label of a song section, e.g. "Verse 2" or "Chorus".
 */
export type SectionLabel = {
  /**
   * What kind of section this is.
   */
  kind: SectionKind;
  /**
   * The section number, e.g. `2` for "Verse 2". `None` for an unnumbered
   * section such as a single "Chorus".
   */
  number: number | null;
  /**
   * The name to display. For known kinds this is normalized ("Verse 2");
   * for [`SectionKind::Other`] it is the tag text as the operator typed it.
   */
  name: string;
};

/**
 * A drop shadow behind the text.
 */
export type Shadow = {
  /**
   * CSS color of the shadow (alpha allowed).
   */
  color: string;
  /**
   * Horizontal offset in reference pixels.
   */
  offsetX: number;
  /**
   * Vertical offset in reference pixels.
   */
  offsetY: number;
  /**
   * Blur radius in reference pixels.
   */
  blur: number;
};

/**
 * The shapes a slide can have.
 */
export type ShapeKind = "rectangle" | "ellipse" | "line";

/**
 * One slide: the text shown on screen at a time.
 */
export type Slide = {
  /**
   * The text to display. Lines are separated by `\n`.
   */
  text: string;
  /**
   * The song section this slide belongs to, if any.
   */
  section: SectionLabel | null;
  /**
   * `true` for the first slide of a section. Jump-to-section shortcuts
   * land on these slides, and the UI shows the section name above them.
   */
  startsSection: boolean;
  /**
   * A line shown with the slide, e.g. the reference "John 3:16–17 (KJV)".
   */
  caption: string | null;
  /**
   * For scripture: the verses laid out in columns, one per translation.
   * `text` then holds a plain-text version of the first column.
   */
  scripture: ScriptureSlide | null;
  /**
   * A background for this slide only (each page of a presentation is
   * its own picture).
   */
  background: Background | null;
  /**
   * For a countdown slide: what it counts down to.
   */
  countdown: CountdownSlide | null;
  /**
   * The text in styled pieces (bold, italic, underline), when a
   * presentation slide uses any. `text` then holds the plain version.
   */
  rich: Array<TextRun> | null;
  /**
   * A theme for this slide only (a presentation slide can have its own).
   */
  look: Look | null;
  /**
   * Adjustments to the theme's text for this slide only.
   */
  style: SlideStyle | null;
  /**
   * For a presentation slide made in the canvas editor: what is on it,
   * back to front. Drawn instead of `text` (which then holds the plain
   * words, for the stage display).
   */
  elements: Array<SlideElement> | null;
};

/**
 * A presentation: a named, ordered list of slides.
 */
export type SlideDeck = {
  /**
   * Unique identifier. Pages imported from a PDF are media items with
   * this as their `collection`.
   */
  id: Id;
  /**
   * The name, e.g. "Announcements" or the PDF's file name.
   */
  name: string;
  /**
   * A theme for the whole deck, instead of the default for presentations.
   */
  themeId: Id | null;
  /**
   * The slides, in order.
   */
  slides: Array<DeckSlide>;
  /**
   * Move to the next slide by itself, e.g. for announcements before the
   * service.
   */
  autoAdvance: AutoAdvance | null;
  /**
   * When it was created.
   */
  createdAt: number;
  /**
   * When it was last changed.
   */
  updatedAt: number;
};

/**
 * One thing on a slide: a text box, a shape or a picture.
 */
export type SlideElement = {
  /**
   * Identifies the element on its slide.
   */
  id: Id;
  /**
   * Shared by "the same" element on different slides (the title box,
   * the logo), so a change can be applied to all slides. Copied when a
   * slide's layout is reused.
   */
  role: Id;
  /**
   * Where it is, in canvas pixels.
   */
  frame: Frame;
  /**
   * How see-through it is, from 0 (invisible) to 1 (solid).
   */
  opacity: number;
  /**
   * Locked elements cannot be moved or resized by accident.
   */
  locked: boolean;
  /**
   * What it is.
   */
  content: ElementContent;
};

/**
 * Options that control how text is split into slides.
 */
export type SlideOptions = {
  /**
   * The most lines a slide may hold. `None` means no limit: only sections
   * and blank lines split slides.
   */
  maxLines: number | null;
};

/**
 * Changes to the theme's text style for one slide. `None` keeps the theme's.
 */
export type SlideStyle = {
  /**
   * Font size in reference pixels.
   */
  fontSize: number | null;
  /**
   * CSS colour of the text.
   */
  color: string | null;
  /**
   * Horizontal alignment.
   */
  align: HorizontalAlign | null;
};

/**
 * A song in the library.
 *
 * Lyrics are kept as tagged plain text (see [`crate::lyrics`]) so the editor
 * shows exactly what was saved, and full-text search can index them as-is.
 */
export type Song = {
  /**
   * Unique identifier.
   */
  id: Id;
  /**
   * Song title, e.g. "Amazing Grace".
   */
  title: string;
  /**
   * Author(s) / songwriter(s), free text.
   */
  author: string;
  /**
   * Copyright notice, e.g. "© 1779 Public Domain".
   */
  copyright: string;
  /**
   * CCLI song number, used for licence reporting. Empty if unknown.
   */
  ccliNumber: string;
  /**
   * Tagged lyric text.
   */
  lyrics: string;
  /**
   * Optional section order, e.g. `"V1 C V2 C B C"`. Empty means document order.
   */
  arrangement: string;
  /**
   * The song's own theme, if it should not use the default song theme.
   */
  themeId: Id | null;
  /**
   * When the song was first saved.
   */
  createdAt: number;
  /**
   * When the song was last saved.
   */
  updatedAt: number;
};

/**
 * A lightweight row for song lists and search results.
 */
export type SongSummary = {
  /**
   * The song's id.
   */
  id: Id;
  /**
   * Song title.
   */
  title: string;
  /**
   * Author(s).
   */
  author: string;
  /**
   * A line of context: the matching lyric excerpt for a search, or the
   * first lyric line when listing.
   */
  excerpt: string;
};

/**
 * One song's line in a usage report.
 */
export type SongUsage = {
  /**
   * Song title.
   */
  title: string;
  /**
   * Author(s).
   */
  author: string;
  /**
   * Copyright notice.
   */
  copyright: string;
  /**
   * CCLI song number (empty if unknown).
   */
  ccliNumber: string;
  /**
   * On how many days it was used in the period.
   */
  times: number;
  /**
   * The last day it was used, `YYYY-MM-DD`.
   */
  lastUsed: string;
};

/**
 * Everything the stage display shows beyond the slides.
 */
export type StageState = {
  /**
   * The speaker's timer, if one is set.
   */
  timer: StageTimer | null;
  /**
   * A message for the people on stage, if any.
   */
  message: string | null;
};

/**
 * A timer on the stage display. Like video, it is an anchor plus a clock:
 * every screen works out the current value from `elapsed_at`.
 */
export type StageTimer = {
  /**
   * Up or down.
   */
  mode: TimerMode;
  /**
   * For a count-down, how long it runs, in milliseconds.
   */
  durationMs: number;
  /**
   * Time counted so far, at `anchor`.
   */
  elapsedMs: number;
  /**
   * When `elapsed_ms` was measured.
   */
  anchor: number;
  /**
   * Whether it is running.
   */
  running: boolean;
};

/**
 * What is behind the words on the stream, where a theme is used (and
 * whenever nothing is showing).
 */
export type StreamBackdrop = "transparent" | "green" | "black" | "main";

/**
 * How the stream shows one kind of content.
 */
export type StreamLook =
  | {
      type: "theme";
      /**
       * The theme, from the library. If it has been deleted, the stream
       * shows the content as the main output does.
       */
      themeId: Id;
    }
  | { type: "sameAsMain" }
  | { type: "hidden" };

/**
 * What the stream draws right now. Part of
 * [`OutputState`](crate::output::OutputState); it shares the main output's
 * transition, video playback and alert.
 */
export type StreamOutput = {
  /**
   * The slide as the stream shows it, or `None` for just the backdrop.
   */
  frame: RenderFrame | null;
  /**
   * Hide the text but keep the slide's pictures (Clear Text on a slide
   * made in the canvas editor).
   */
  hideText: boolean;
  /**
   * Leave out the slide's own background (Clear Background).
   */
  hideBackground: boolean;
  /**
   * The CSS colour behind everything.
   */
  backdrop: string;
  /**
   * Show the main output's alert.
   */
  showAlerts: boolean;
};

/**
 * The stream look, chosen in Settings › Stream and saved by the host.
 */
export type StreamSettings = {
  /**
   * Songs.
   */
  songs: StreamLook;
  /**
   * Bible passages.
   */
  scripture: StreamLook;
  /**
   * Presentations, imported PDFs and slideshows.
   */
  presentations: StreamLook;
  /**
   * Everything else: typed text, pictures, videos, countdowns.
   */
  other: StreamLook;
  /**
   * What is behind the words.
   */
  backdrop: StreamBackdrop;
  /**
   * Show alerts (nursery calls, notices) on the stream as well.
   */
  showAlerts: boolean;
};

/**
 * The outline of a shape.
 */
export type Stroke = {
  /**
   * CSS colour.
   */
  color: string;
  /**
   * Width in canvas pixels.
   */
  width: number;
};

/**
 * The rectangle the slide text is laid out in.
 */
export type TextBox = {
  /**
   * Distance from the top edge, in reference pixels.
   */
  top: number;
  /**
   * Distance from the right edge, in reference pixels.
   */
  right: number;
  /**
   * Distance from the bottom edge, in reference pixels.
   */
  bottom: number;
  /**
   * Distance from the left edge, in reference pixels.
   */
  left: number;
  /**
   * Vertical placement of the text inside the box.
   */
  verticalAlign: VerticalAlign;
  /**
   * Shrink the font (down from [`TextStyle::font_size`]) until the text fits.
   */
  autoFit: boolean;
  /**
   * Scale font up or down to auto fit container bounds.
   */
  scaleUp: boolean;
};

/**
 * A piece of text in one style. Line breaks stay in the text as `\n`.
 *
 * Colour, size and font are only set where they differ from the text
 * box's own style (`None` follows the box).
 */
export type TextRun = {
  /**
   * The text.
   */
  text: string;
  /**
   * Bold.
   */
  bold: boolean;
  /**
   * Italic.
   */
  italic: boolean;
  /**
   * Underlined.
   */
  underline: boolean;
  /**
   * CSS colour.
   */
  color?: string | null;
  /**
   * Font size in reference pixels (scaled with the box when it shrinks
   * to fit).
   */
  fontSize?: number | null;
  /**
   * CSS font family list.
   */
  fontFamily?: string | null;
};

/**
 * Font and decoration for slide text.
 */
export type TextStyle = {
  /**
   * CSS font family list, e.g. `"Open Sans, Arial, sans-serif"`.
   */
  fontFamily: string;
  /**
   * Font size in reference pixels. With [`TextBox::auto_fit`] on, this is
   * the *maximum* size.
   */
  fontSize: number;
  /**
   * CSS font weight, e.g. 400 (regular) or 700 (bold).
   */
  fontWeight: number;
  /**
   * Use italics.
   */
  italic: boolean;
  /**
   * Show the text in capital letters.
   */
  uppercase: boolean;
  /**
   * CSS color of the text.
   */
  color: string;
  /**
   * Line height as a multiple of the font size.
   */
  lineHeight: number;
  /**
   * Horizontal alignment.
   */
  align: HorizontalAlign;
  /**
   * Outline drawn around each letter. Helps text stay readable on busy backgrounds.
   */
  outline: Outline | null;
  /**
   * Drop shadow behind the text.
   */
  shadow: Shadow | null;
};

/**
 * A complete visual style for slides.
 */
export type Theme = {
  /**
   * Display name, e.g. "Default".
   */
  name: string;
  /**
   * What is drawn behind the text.
   */
  background: Background;
  /**
   * How the slide text looks.
   */
  text: TextStyle;
  /**
   * The area the text is laid out in.
   */
  textBox: TextBox;
  /**
   * How the footer (copyright / CCLI line) looks, and where it sits.
   */
  footer: FooterStyle;
  /**
   * How the scripture reference ("John 3:16 (KJV)") looks, and where it sits.
   */
  caption: FooterStyle;
  /**
   * Settings that only apply to scripture.
   */
  scripture: ScriptureStyle;
  /**
   * Target category: "song", "scripture", "presentation", "text", or None.
   */
  category: string | null;
};

/**
 * Which theme each kind of content uses by default.
 */
export type ThemeDefaults = {
  /**
   * Theme for songs.
   */
  song: Id | null;
  /**
   * Theme for scripture.
   */
  scripture: Id | null;
  /**
   * Theme for free text.
   */
  text: Id | null;
  /**
   * Theme for presentations and slideshows. When unset, they use the
   * free-text theme.
   */
  presentation: Id | null;
};

/**
 * Every theme, plus the defaults. The host sends this to the engine at
 * startup and whenever a theme changes.
 */
export type ThemeLibrary = {
  /**
   * The themes, in the order the operator sees them.
   */
  themes: Array<ThemeRecord>;
  /**
   * The default theme for each kind of content.
   */
  defaults: ThemeDefaults;
};

/**
 * A theme in the library.
 */
export type ThemeRecord = {
  /**
   * Unique identifier.
   */
  id: Id;
  /**
   * The theme (including its name).
   */
  theme: Theme;
  /**
   * One of the starter themes that ship with SimpleWorship.
   */
  builtin: boolean;
};

/**
 * Which way a stage timer counts.
 */
export type TimerMode = "countUp" | "countDown";

/**
 * How the output changes from one frame to the next.
 */
export type Transition = {
  /**
   * The kind of transition.
   */
  kind: TransitionKind;
  /**
   * How long it takes, in milliseconds. Ignored for [`TransitionKind::Cut`].
   */
  durationMs: number;
};

/**
 * The available transitions.
 */
export type TransitionKind = "cut" | "fade";

/**
 * The transition for each kind of content, as in EasyWorship: a church
 * might cut straight to scripture during preaching but fade between song
 * slides. Saved by the host, so it is the same after a restart.
 */
export type TransitionSettings = {
  /**
   * For songs.
   */
  songs: Transition;
  /**
   * For Bible passages.
   */
  scripture: Transition;
  /**
   * For presentations, imported PDFs and slideshows.
   */
  presentations: Transition;
  /**
   * For everything else: typed text, pictures, videos, countdowns.
   */
  other: Transition;
};

/**
 * The verses of a passage in one translation, with what is needed to label
 * and credit it. Stored inside schedule items, so a saved schedule shows
 * the same text on a computer without that Bible.
 */
export type TranslationText = {
  /**
   * The Bible the text came from.
   */
  bibleId: Id;
  /**
   * Its short name, e.g. "KJV".
   */
  abbreviation: string;
  /**
   * Its copyright notice.
   */
  copyright: string;
  /**
   * The verses, in order.
   */
  verses: Array<Verse>;
};

/**
 * One verse of one translation.
 */
export type Verse = {
  /**
   * The book.
   */
  book: BookId;
  /**
   * Chapter number.
   */
  chapter: number;
  /**
   * Verse number.
   */
  verse: number;
  /**
   * The text.
   */
  text: string;
};

/**
 * A verse (or part of one) on a slide.
 */
export type VerseLine = {
  /**
   * The verse number.
   */
  number: number;
  /**
   * The text; empty if this translation lacks the verse.
   */
  text: string;
  /**
   * `true` for the second and later parts of a verse split across slides.
   * Continued parts show no verse number.
   */
  continued: boolean;
};

/**
 * How the verse numbers in scripture look.
 */
export type VerseNumberStyle = {
  /**
   * Show them. The Scripture tab can override this for one passage.
   */
  visible: boolean;
  /**
   * CSS color, or empty for the verse text's colour (slightly faded).
   */
  color: string;
  /**
   * Size as a percentage of the verse text.
   */
  sizePercent: number;
  /**
   * Raised above the line (superscript), or in line with the text.
   */
  superscript: boolean;
  /**
   * Bold.
   */
  bold: boolean;
};

/**
 * Vertical placement of the text block inside the text box.
 */
export type VerticalAlign = "top" | "middle" | "bottom";

/**
 * Where the live video is, shared by every screen that shows it.
 *
 * Instead of streaming the position many times a second, the engine says
 * "at wall-clock time `anchor`, the video was at `position_ms`, and it is
 * (or is not) playing". Each screen works out the current position from
 * its own clock with [`VideoPlayback::position_at`], so the projector, the
 * operator's live pane and any future remote screen stay in step.
 */
export type VideoPlayback = {
  /**
   * The video this playback belongs to.
   */
  mediaId: Id;
  /**
   * Whether the video is playing.
   */
  playing: boolean;
  /**
   * The position, in milliseconds, at `anchor`.
   */
  positionMs: number;
  /**
   * When `position_ms` was measured (milliseconds since the Unix epoch).
   */
  anchor: number;
  /**
   * Start again from the beginning at the end.
   */
  loop: boolean;
  /**
   * Silence the video's sound on every screen. Starts from the
   * background's "play sound" setting; the operator can change it live.
   */
  muted: boolean;
};
